import {readFileSync,readdirSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {SourceTextModule,SyntheticModule} from 'node:vm';
import {createHash} from 'node:crypto';
import {renderSchematicSvg} from 'bw-circuit-ui/model/schematic-svg.js';
import {Circuit} from 'bw-circuit-ui/model/circuit.js';
import {setEngine} from 'bw-circuit-ui/engine.js';
import {registerSidecar} from 'bw-circuit-ui/model/parts-registry.js';
const uiRepo='/home/agent/.codex/skills/remote-skills/.worktrees/bw-circuit-ui-microtronic';
const source=readFileSync('overlay/scratch-gui/examples/10-motor-speed/circuit.pico.json','utf8');
const golden=readFileSync('docs/schematic-baselines/10-motor-speed-circuit.pico.svg','utf8');
class AuditBoard {setNetlist(){}snapshot(){return null;}}
const engine={BoardImpl:AuditBoard,inferNetlist:()=>({}),checkWiring:()=>[]};
setEngine(engine);
for(const f of readdirSync('node_modules/bw-circuit-ui/src/parts-data'))if(f.endsWith('.json'))registerSidecar(JSON.parse(readFileSync('node_modules/bw-circuit-ui/src/parts-data/'+f,'utf8')));
const c=Circuit.fromJSON(JSON.parse(source));
const installed=renderSchematicSvg({parts:c.parts,nets:c.resolvedNets},{dark:false});
async function renderGit(rev){
 const modules=new Map();const git=(...args)=>execFileSync('git',['-C',uiRepo,...args],{encoding:'utf8'});
 const get=(path)=>{
  if(modules.has(path))return modules.get(path);
  const source=git('show',rev+':'+path);
  const m=path.endsWith('.json')?new SyntheticModule(['default'],function(){this.setExport('default',JSON.parse(source));},{identifier:'git:/'+rev+'/'+path}):new SourceTextModule(source,{identifier:'git:/'+rev+'/'+path,initializeImportMeta(meta,mod){meta.url=mod.identifier;}});
  modules.set(path,m);return m;
 };
 const linker=(specifier,reference)=>{
  if(!specifier.startsWith('.'))throw Error('Unexpected external import '+specifier+' in '+reference.identifier);
  return get(new URL(specifier,reference.identifier).pathname.split('/').slice(2).join('/'));
 };
 const ns=async path=>{const m=get(path);if(m.status==='unlinked')await m.link(linker);if(m.status==='linked')await m.evaluate();return m.namespace;};
 const e=await ns('src/engine.js');e.setEngine(engine);
 const registry=await ns('src/model/parts-registry.js');
 for(const p of git('ls-tree','-r','--name-only',rev,'src/parts-data').trim().split('\n').filter(p=>p.endsWith('.json')))registry.registerSidecar(JSON.parse(git('show',rev+':'+p)));
 const model=await ns('src/model/circuit.js');const renderer=await ns('src/model/schematic-svg.js');
 const c=model.Circuit.fromJSON(JSON.parse(source));const rendered=renderer.renderSchematicSvg({parts:c.parts,nets:c.resolvedNets},{dark:false});
 return {rendered,modules:[...modules.keys()].sort()};
}
const old=await renderGit('11532a80eee13b7dad4451e167dc6780bd546ea0');
const current=await renderGit('0a1b15edb0daecd723c7c07126450d84b86e3e68');
const hash=s=>createHash('sha256').update(s).digest('hex');
console.log(JSON.stringify({golden,installed:installed.svg,old:old.rendered.svg,current:current.rendered.svg,summary:{hashes:{golden:hash(golden),installed:hash(installed.svg),old:hash(old.rendered.svg),current:hash(current.rendered.svg)},oldEqualsNew:old.rendered.svg===current.rendered.svg,newEqualsInstalled:current.rendered.svg===installed.svg,oldEqualsGolden:old.rendered.svg===golden,metadata:{width:installed.width,height:installed.height,symbols:installed.symbols,wires:installed.wires,generic:installed.generic,wireSymbolCrossings:installed.wireSymbolCrossings,symbolOverlaps:installed.symbolOverlaps},oldModuleCount:old.modules.length,currentModuleCount:current.modules.length,modules:current.modules}}));
